// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "0", "0");
    }

    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        vm.assume(initialSupply > 0 && initialSupply < type(uint256).max / 10**18);
        vm.assume(burnAmount > 0 && burnAmount <= initialSupply);

        c = new ERCDDAToken(initialSupply, "T", "S");
        uint256 supplyBefore = c.totalSupply();

        vm.prank(c.owner());
        c.burn(burnAmount * 10**uint256(c.decimals()));

        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter <= supplyBefore);
    }
}
